import Foundation
import AVFoundation
import CoreMedia
import PhotoContainers

// Headless acceptance for AVI playback. Shared by `pv-pipeline` and the
// XCTest target; the fixtures are generated by scripts/make_avi_fixtures.sh.

/// Every playable fixture builds a movie whose every video frame and audio
/// packet decodes, and whose picture renders as a thumbnail.
public func verifyAVIFixturesDecode() async throws {
    let fixtures: [(name: String, frames: Int, audioTracks: Int, seconds: Double)] = [
        ("xvid-mp3", 45, 1, 1.45), ("xvid-ac3", 45, 1, 1.45), ("xvid-mp2", 45, 1, 1.45),
        ("h264-mp3", 45, 1, 1.45), ("h264-aac", 45, 1, 1.45), ("mjpeg-ima", 45, 1, 1.45),
        ("camera-mjpeg", 45, 1, 1.45), ("opendml-cbr", 45, 3, 1.45), ("opendml-vbr", 45, 3, 1.45),
        ("dv-pcm", 1, 1, 0.02), ("ms-adpcm", 0, 1, 1.45), ("alaw", 0, 1, 1.45), ("ulaw", 0, 1, 1.45),
    ]
    for fixture in fixtures {
        let movie = try await ReferenceMovie.open(url: try aviFixture(fixture.name))
        try check(movie.skippedTracks.isEmpty, "\(fixture.name): skipped \(movie.skippedTracks.map(\.reason))")
        try check(movie.videoTrackCount == (fixture.frames > 0 ? 1 : 0) && movie.audioTrackCount == fixture.audioTracks,
                  "\(fixture.name): \(movie.videoTrackCount) video and \(movie.audioTrackCount) audio tracks")
        try check(movie.isComplete, "\(fixture.name): reported incomplete")
        let decoded = try await MediaChecks.decodeAll(movie.asset)
        try check(decoded.videoFrames == fixture.frames,
                  "\(fixture.name): decoded \(decoded.videoFrames) of \(fixture.frames) video frames")
        try check(decoded.audioSeconds >= fixture.seconds,
                  "\(fixture.name): only \(decoded.audioSeconds)s of audio decoded")
        if fixture.frames > 0 {
            let image = try await AVAssetImageGenerator(asset: movie.asset).image(at: .zero).image
            try check(image.width > 0 && image.height > 0, "\(fixture.name): empty thumbnail")
        }
    }

    // DV says in its own frames whether the picture is 16:9; this one is.
    let dv = try await ReferenceMovie.open(url: try aviFixture("dv-pcm"))
    guard let track = try await dv.asset.loadTracks(withMediaType: .video).first,
          let format = try await track.load(.formatDescriptions).first else { throw failure("dv-pcm: no video format") }
    let aspect = CMFormatDescriptionGetExtension(format, extensionKey: kCMFormatDescriptionExtension_PixelAspectRatio)
        as? [String: Int]
    try check(aspect?[kCMFormatDescriptionKey_PixelAspectRatioHorizontalSpacing as String] == 32
              && aspect?[kCMFormatDescriptionKey_PixelAspectRatioVerticalSpacing as String] == 27,
              "dv-pcm: a 16:9 NTSC DV frame should have 32:27 pixels, not \(String(describing: aspect))")
}

/// AVI has no timestamps, so where a frame or a sound plays is a reading of
/// the file, and Latent reads it the way ffmpeg (and so VLC and mpv) does:
/// chunk n of a stream plays n frame or packet durations in, a dropped frame
/// still takes its slot, and reordered H.264 shows each picture after the
/// deepest reordering delay. The flash and click times below are ffmpeg's
/// for these exact files (`signalstats` and `silencedetect`). The one
/// deliberate difference is the decoder delay of MPEG audio and AC-3, which
/// ffmpeg plays as leading silence and AVFoundation hides, exactly as it
/// does for the same streams in Matroska and MP4.
public func verifyAVIAudioSync() async throws {
    let fixtures: [(name: String, flash: Double?, click: Double, hidden: Double)] = [
        ("xvid-mp3", 1.033333, 1.025125, 529.0 / 44100),     // ffmpeg left frame 1 empty
        ("xvid-ac3", 1.0, 1.005396, 256.0 / 48000),
        ("xvid-mp2", 1.0, 1.010083, 241.0 / 48000),
        ("h264-mp3", 1.066667, 1.023083, 529.0 / 48000),     // two frames of B-frame delay
        ("h264-aac", 1.033333, 1.021396, 0),                  // AAC priming plays in ffmpeg too
        ("mjpeg-ima", 1.0, 1.000816, 0),
        ("camera-mjpeg", 1.0, 1.0 + 1.0 / 11025, 0),          // written sample by sample
        ("opendml-cbr", 1.033333, 1.025125, 529.0 / 44100),  // xvid-mp3's video and MP3 frames
        ("ms-adpcm", nil, 1.00075, 0), ("alaw", nil, 1.000125, 0), ("ulaw", nil, 1.000125, 0),
    ]
    for fixture in fixtures {
        let movie = try await ReferenceMovie.open(url: try aviFixture(fixture.name))
        let expected = fixture.click - fixture.hidden
        let click: Double
        if let flashAt = fixture.flash {
            let found = try await MediaChecks.flashAndClick(movie.asset)
            try check(abs(found.flash - flashAt) < 0.001,
                      "\(fixture.name): flash at \(found.flash)s instead of \(flashAt)s")
            click = found.click
        } else {
            click = try await MediaChecks.click(movie.asset)
        }
        try check(abs(click - expected) < 0.001,
                  "\(fixture.name): click at \(click)s instead of \(expected)s (\(String(format: "%+.2f", (click - expected) * 1000)) ms)")
    }
}

/// The same streams come out the same whichever way the file says where
/// its chunks are: an OpenDML index spread over two RIFFs, a legacy idx1
/// (relative or absolute), or no index at all. Damaged and partly read
/// files keep what they have.
public func verifyAVIIndexes() async throws {
    // OpenDML and idx1 describe opendml-cbr's and opendml-vbr's shared
    // video identically, keyframe flags (bit 31 of each entry) included.
    let openDML = try AVIIndex.read(url: try aviFixture("opendml-cbr"))
    let legacy = try AVIIndex.read(url: try aviFixture("opendml-vbr"))
    try check(openDML.isComplete, "opendml-cbr: reported incomplete")
    let odmlVideo = try videoFrames(openDML, "opendml-cbr")
    let legacyVideo = try videoFrames(legacy, "opendml-vbr")
    try check(odmlVideo.count == 45, "opendml-cbr: \(odmlVideo.count) video frames, not 45")
    try check(odmlVideo.map(\.size) == legacyVideo.map(\.size) && odmlVideo.map(\.timestamp) == legacyVideo.map(\.timestamp),
              "OpenDML and idx1 disagree about the video frames")
    try check(odmlVideo.map(\.isKeyframe) == legacyVideo.map(\.isKeyframe),
              "OpenDML keyframes \(odmlVideo.map(\.isKeyframe)) != idx1's")
    try check(odmlVideo.contains { $0.isKeyframe } && odmlVideo.contains { !$0.isKeyframe },
              "opendml-cbr should mix keyframes and delta frames")

    // xvid-mp3's idx1 counts from the movie list, camera-mjpeg's from the
    // start of the file. A file whose idx1 is gone is walked chunk by chunk
    // and comes out the same, MPEG-4 keyframes recognized from the frames
    // themselves. And the index really is what's read: with every chunk
    // header but the first renamed to JUNK, which a walk skips, the idx1
    // read still finds every frame.
    for name in ["xvid-mp3", "camera-mjpeg"] {
        let url = try aviFixture(name)
        let original = try Data(contentsOf: url)
        let indexed = try AVIIndex.read(url: url)
        guard let idx1 = original.range(of: Data("idx1".utf8), options: .backwards) else { throw failure("\(name): no idx1") }

        var unindexed = original
        unindexed.replaceSubrange(idx1, with: Data("JUNK".utf8))
        let scannedURL = try MediaChecks.writeTemporary(unindexed, name: "\(name)-noindex.avi")
        defer { try? FileManager.default.removeItem(at: scannedURL) }
        let scanned = try AVIIndex.read(url: scannedURL)
        try check(scanned.tracks.count == indexed.tracks.count, "\(name): scan found \(scanned.tracks.count) tracks")
        for (a, b) in zip(indexed.tracks, scanned.tracks) {
            try check(placement(a.frames) == placement(b.frames),
                      "\(name): track \(a.number) differs between idx1 and a scan")
        }

        var hidden = original
        let first = indexed.tracks.flatMap(\.frames).map(\.offset).min() ?? 0
        for frame in indexed.tracks.flatMap(\.frames) where frame.offset != first {
            let header = Int(frame.offset) - 8
            hidden.replaceSubrange(header..<(header + 4), with: Data("JUNK".utf8))
        }
        let hiddenURL = try MediaChecks.writeTemporary(hidden, name: "\(name)-hidden.avi")
        defer { try? FileManager.default.removeItem(at: hiddenURL) }
        let fromIndex = try AVIIndex.read(url: hiddenURL)
        for (a, b) in zip(indexed.tracks, fromIndex.tracks) {
            try check(placement(a.frames) == placement(b.frames),
                      "\(name): track \(a.number) was not read from idx1")
        }
    }

    // An idx1 that flags no keyframes says nothing about them; MPEG-4
    // frames still name their own.
    let xvid = try Data(contentsOf: try aviFixture("xvid-mp3"))
    guard let idx1 = xvid.range(of: Data("idx1".utf8), options: .backwards) else { throw failure("xvid-mp3: no idx1") }
    let entries = (0..<4).reduce(0) { $0 | Int(xvid[idx1.lowerBound + 4 + $1]) << (8 * $1) } / 16
    var unflagged = xvid
    for entry in 0..<entries {
        let flags = idx1.lowerBound + 8 + 16 * entry + 4
        unflagged.replaceSubrange(flags..<(flags + 4), with: Data(count: 4))
    }
    let unflaggedURL = try MediaChecks.writeTemporary(unflagged, name: "unflagged.avi")
    defer { try? FileManager.default.removeItem(at: unflaggedURL) }
    let flagged = try videoFrames(try AVIIndex.read(url: try aviFixture("xvid-mp3")), "xvid-mp3").map(\.isKeyframe)
    let recovered = try videoFrames(try AVIIndex.read(url: unflaggedURL), "unflagged xvid-mp3").map(\.isKeyframe)
    try check(recovered == flagged && recovered.contains(false),
              "an unflagged idx1 gave keyframes \(recovered), not \(flagged)")

    // A download cut off partway plays what arrived.
    let whole = try Data(contentsOf: try aviFixture("xvid-mp3"))
    let cutURL = try MediaChecks.writeTemporary(whole.prefix(whole.count * 6 / 10), name: "cut.avi")
    defer { try? FileManager.default.removeItem(at: cutURL) }
    let cut = try ReferenceMovie.load(url: cutURL)
    try check(!cut.isComplete, "a cut-off file must read as incomplete")
    let cutDecoded = try await MediaChecks.decodeAll(cut.asset)
    try check((15..<45).contains(cutDecoded.videoFrames), "a cut-off file decoded \(cutDecoded.videoFrames) frames")

    // A thumbnail read stops half a second past its limit and keeps a
    // second of sound past the last frame.
    let partial = try AVIIndex.read(url: try aviFixture("xvid-mp3"), limit: 0.3)
    let partialVideo = try videoFrames(partial, "limited xvid-mp3")
    let partialAudio = partial.tracks.first { $0.kind == .audio }?.frames ?? []
    try check(!partial.isComplete, "a limited read must report incomplete")
    try check(partialVideo.count < 30 && (partialVideo.last?.timestamp ?? .max) <= 850_000_000,
              "a 0.3 s limit read \(partialVideo.count) frames to \(partialVideo.last?.timestamp ?? -1) ns")
    try check(!partialAudio.isEmpty && partialAudio.last!.timestamp <= partialVideo.last!.timestamp + 1_000_000_000,
              "a limited read kept audio to \(partialAudio.last?.timestamp ?? -1) ns")
    // Without video, the sound is kept to a second past the limit.
    let partialSound = try AVIIndex.read(url: try aviFixture("alaw"), limit: 0.2)
    let soundEnd = partialSound.tracks.first?.frames.last?.timestamp ?? .max
    try check(!partialSound.isComplete && soundEnd <= 1_200_000_000,
              "a 0.2 s limit on alaw kept audio to \(soundEnd) ns")

    // Type-1 DV keeps its sound inside the video frames: the picture plays
    // and the viewer is told why that sound doesn't.
    var dv = try Data(contentsOf: try aviFixture("dv-pcm"))
    guard let vids = dv.range(of: Data("vids".utf8)) else { throw failure("dv-pcm: no video stream header") }
    dv.replaceSubrange(vids, with: Data("iavs".utf8))
    let typeOneURL = try MediaChecks.writeTemporary(dv, name: "type1.avi")
    defer { try? FileManager.default.removeItem(at: typeOneURL) }
    let typeOne = try ReferenceMovie.load(url: typeOneURL)
    try check(typeOne.videoTrackCount == 1, "type-1 DV video should play")
    try check(typeOne.skippedTracks.contains { $0.kind == .audio && $0.reason.contains("DV video frames") },
              "type-1 DV should explain its sound: \(typeOne.skippedTracks.map(\.reason))")
}

/// Constant-bitrate audio is one byte stream that AVI cuts into chunks
/// regardless of packets. opendml-cbr cuts MP3 frames, ADPCM blocks and
/// AC-3 frames mid-packet; opendml-vbr stores the same packets one per
/// chunk. Both
/// must decode to the same samples from the same instant, which only
/// happens when every packet is re-cut on exactly the right bytes. H.264's
/// rewritten copy lives exactly as long as something can play it.
public func verifyAVIRepacketizing() async throws {
    let cut = try await ReferenceMovie.open(url: try aviFixture("opendml-cbr"))
    let whole = try await ReferenceMovie.open(url: try aviFixture("opendml-vbr"))
    try check(cut.scratchFileURLs.count == 3, "opendml-cbr: expected MP3, ADPCM and AC-3 re-cut into scratch files")
    try check(whole.scratchFileURLs.isEmpty, "opendml-vbr: packets already one per chunk need no copy")
    for (track, name) in [(0, "MP3"), (1, "IMA ADPCM"), (2, "AC-3")] {
        let a = try await MediaChecks.decodePCM16(cut.asset, track: track)
        let b = try await MediaChecks.decodePCM16(whole.asset, track: track)
        try check(a.samples.count > 10_000, "\(name): only \(a.samples.count) samples decoded")
        try check(a.samples == b.samples,
                  "\(name): re-cut audio decodes differently (\(a.samples.count) vs \(b.samples.count) samples)")
        try check(a.start == b.start, "\(name): re-cut audio starts at \(a.start.seconds)s, not \(b.start.seconds)s")
    }

    // Variable-bitrate MP3 packed two frames to a chunk, and AAC behind
    // ADTS headers, are re-cut in place and decode like the same packets
    // stored one per chunk.
    for (name, reference, label) in [("mp3-packed", "opendml-vbr", "packed MP3"), ("aac-adts", "h264-aac", "ADTS AAC")] {
        let movie = try await ReferenceMovie.open(url: try aviFixture(name))
        let original = try await ReferenceMovie.open(url: try aviFixture(reference))
        try check(movie.audioTrackCount == 1 && movie.scratchFileURLs.isEmpty,
                  "\(label): expected its audio read in place, skipped \(movie.skippedTracks.map(\.reason))")
        let a = try await MediaChecks.decodePCM16(movie.asset)
        let b = try await MediaChecks.decodePCM16(original.asset)
        try check(a.samples.count > 10_000 && a.samples == b.samples,
                  "\(label): decodes differently (\(a.samples.count) vs \(b.samples.count) samples)")
        try check(a.start == b.start, "\(label): starts at \(a.start.seconds)s, not \(b.start.seconds)s")
    }

    // mjpeg-ima's chunks hold whole ADPCM blocks: split in place, no copy.
    let aligned = try ReferenceMovie.load(url: try aviFixture("mjpeg-ima"))
    try check(aligned.scratchFileURLs.isEmpty, "mjpeg-ima: whole-block chunks should be split in place")

    // A player holding only the asset keeps the H.264 copy; letting go of
    // the asset deletes it.
    var urls: [URL] = []
    var asset: AVAsset? = try autoreleasepool {
        let movie = try ReferenceMovie.load(url: try aviFixture("h264-mp3"))
        urls = movie.scratchFileURLs
        return movie.asset
    }
    try check(urls.count == 1, "h264-mp3: expected one scratch file, found \(urls.count)")
    try check(urls.allSatisfy { FileManager.default.fileExists(atPath: $0.path) }, "the asset's scratch file is gone")
    try check(asset != nil, "asset released early")
    autoreleasepool { asset = nil }
    try check(urls.allSatisfy { !FileManager.default.fileExists(atPath: $0.path) },
              "the scratch file outlived its movie and asset")
}

/// Streams macOS can't decode are left out with a reason the viewer shows
/// while the rest plays; files that aren't playable AVIs fail with one.
public func verifyAVIRejectsUnplayable() async throws {
    for (name, phrase) in [("divx3", "DivX 3"), ("xvid-bframes", "DivX or Xvid"), ("mjpeg-422", "Motion JPEG")] {
        let movie = try await ReferenceMovie.open(url: try aviFixture(name))
        try check(movie.videoTrackCount == 0 && movie.audioTrackCount == 1, "\(name): only its audio should play")
        try check(movie.skippedTracks.count == 1 && movie.skippedTracks[0].reason.contains(phrase),
                  "\(name): reason should mention \(phrase): \(movie.skippedTracks.map(\.reason))")
    }

    let cases: [(String, Data, (ContainerError) -> Bool)] = [
        ("a WAV file", SyntheticAVI.riff("WAVE", [SyntheticAVI.chunk("fmt ", SyntheticAVI.waveFormat(tag: 1)),
                                                  SyntheticAVI.chunk("data", Data(count: 64))]),
         { $0 == .unrecognized }),
        ("an AVI with no streams", SyntheticAVI.avi(streams: [], movie: []), { $0 == .noPlayableTracks([]) }),
        ("an AVI with no movie data", SyntheticAVI.avi(streams: [SyntheticAVI.audioStream(tag: 1)], movie: nil),
         { $0 == .noMovieData }),
        ("an AVI with only DTS audio", SyntheticAVI.avi(streams: [SyntheticAVI.audioStream(tag: 0x2001)],
                                                        movie: [SyntheticAVI.chunk("00wb", Data(count: 32))]), {
            if case .noPlayableTracks(let reasons) = $0 { return reasons.contains { $0.contains("DTS") } }
            return false
        }),
    ]
    for (label, data, expected) in cases {
        let url = try MediaChecks.writeTemporary(data, name: "reject.avi")
        defer { try? FileManager.default.removeItem(at: url) }
        do {
            _ = try ReferenceMovie.load(url: url)
            throw failure("\(label): loaded instead of failing")
        } catch let error as ContainerError {
            try check(expected(error), "\(label): unexpected error \(error)")
            try check(!error.description.isEmpty, "\(label): error has no description")
        }
    }
}

// MARK: - Helpers

private struct VerificationFailure: Error, CustomStringConvertible {
    let description: String
}

private func failure(_ message: String) -> VerificationFailure {
    VerificationFailure(description: message)
}

private func check(_ condition: Bool, _ message: @autoclosure () -> String) throws {
    if !condition { throw failure(message()) }
}

private func aviFixture(_ name: String) throws -> URL {
    guard let url = Bundle.module.url(forResource: name, withExtension: "avi", subdirectory: "AVI") else {
        throw failure("missing fixture \(name).avi")
    }
    return url
}

private func videoFrames(_ index: MatroskaIndex, _ label: String) throws -> [MatroskaFrame] {
    guard let track = index.tracks.first(where: { $0.kind == .video }) else { throw failure("\(label): no video track") }
    return track.frames
}

/// Where and when each frame is, leaving out the bytes a scan captures
/// that an index read does not.
private func placement(_ frames: [MatroskaFrame]) -> [[Int64]] {
    frames.map { [$0.offset, Int64($0.size), $0.timestamp, $0.isKeyframe ? 1 : 0] }
}

/// Writes tiny RIFF files for the failure cases.
private enum SyntheticAVI {
    static func le16(_ value: Int) -> Data { Data([UInt8(value & 0xFF), UInt8(value >> 8 & 0xFF)]) }
    static func le32(_ value: Int) -> Data { le16(value & 0xFFFF) + le16(value >> 16 & 0xFFFF) }

    static func chunk(_ id: String, _ body: Data) -> Data {
        Data(id.utf8) + le32(body.count) + body + (body.count & 1 == 1 ? Data([0]) : Data())
    }

    static func list(_ type: String, _ children: [Data]) -> Data {
        chunk("LIST", Data(type.utf8) + children.reduce(Data(), +))
    }

    static func riff(_ form: String, _ children: [Data]) -> Data {
        chunk("RIFF", Data(form.utf8) + children.reduce(Data(), +))
    }

    static func waveFormat(tag: Int) -> Data {
        le16(tag) + le16(2) + le32(48000) + le32(192_000) + le16(4) + le16(16) + le16(0)
    }

    static func audioStream(tag: Int) -> Data {
        var header = Data("auds".utf8) + Data(count: 4) + Data(count: 12) // handler, flags, priority, language, initial
        header += le32(1) + le32(48000) + Data(count: 16) + le32(4) + Data(count: 8) // scale, rate, ..., sample size
        return list("strl", [chunk("strh", header), chunk("strf", waveFormat(tag: tag))])
    }

    /// An AVI whose header lists `streams`, with a movie list holding
    /// `movie`'s chunks, or none at all when it is nil.
    static func avi(streams: [Data], movie: [Data]?) -> Data {
        let header = list("hdrl", [chunk("avih", Data(count: 56))] + streams)
        return riff("AVI ", [header] + (movie.map { [list("movi", $0)] } ?? []))
    }
}
